    insert into hr_contacts (person_id, email, phone)
    values (p_person_id, p_email, p_phone)
    on conflict (person_id) do update; -- Using MERGE/UPSERT logic conceptually, but sticking to simple insert/update if possible based on schema.
    -- Since HR_CONTACTS has person_id as PK, we should use MERGE or check existence.
